package com.bank.hints.repository;

import com.bank.hints.model.Account;
import jakarta.persistence.QueryHint;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.List;
import java.util.stream.Stream;

public interface AccountRepository extends JpaRepository<Account, String> {

    // readOnly hint: no dirty-check snapshot for these entities
    @QueryHints(@QueryHint(name = "org.hibernate.readOnly", value = "true"))
    @Query("select a from Account a where a.status = :status")
    List<Account> listReadOnly(@Param("status") String status);

    // cacheable hint: cache the rarely-changing branch list
    @QueryHints(@QueryHint(name = "org.hibernate.cacheable", value = "true"))
    @Query("select distinct a.branchCode from Account a")
    List<String> branchCodesCached();

    // fetchSize + readOnly: stream a huge export memory-safely
    @QueryHints({
        @QueryHint(name = "org.hibernate.fetchSize", value = "1000"),
        @QueryHint(name = "org.hibernate.readOnly", value = "true")
    })
    @Query("select a from Account a")
    Stream<Account> streamAll();

    // timeout hint: abort a slow customer-facing search after 3s
    @QueryHints(@QueryHint(name = "jakarta.persistence.query.timeout", value = "3000"))
    @Query("select a from Account a where a.holderName like :name")
    List<Account> searchByName(@Param("name") String name);
}
