package com.bank.hints.service;

import com.bank.hints.model.Account;
import com.bank.hints.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;
import java.util.stream.Stream;

@Slf4j
@Service
@RequiredArgsConstructor
public class ReportService {
    private final AccountRepository repo;

    @Transactional(readOnly = true)
    public List<Account> activeList() {
        return repo.listReadOnly("ACTIVE");          // method-level readOnly hint
    }

    @Transactional(readOnly = true)
    public List<String> branches() {
        return repo.branchCodesCached();             // cacheable
    }

    // stream must stay inside the transaction while consumed
    @Transactional(readOnly = true)
    public long exportCount() {
        try (Stream<Account> s = repo.streamAll()) { // fetchSize 1000, memory-safe
            long count = s.count();
            log.info("Streamed {} accounts for export", count);
            return count;
        }
    }

    @Transactional(readOnly = true)
    public List<Account> search(String namePattern) {
        return repo.searchByName(namePattern);        // 3s query timeout
    }
}
